namespace InventoryTracker.Api.Domain;

/// <summary>
/// One raw material of a production order, with the figures fixed at creation, send and completion.
/// Table <c>ProductionOrderLines</c>.
/// </summary>
/// <remarks>
/// The fields are grouped by the moment they are fixed. Nullable fields are null until that moment (AC-14.2:
/// "values not yet known are empty"). The calculations themselves are pure functions in
/// <c>Domain/Calculations</c> (T-004); this class only stores their results.
/// </remarks>
public class ProductionOrderLine
{
    /// <summary>Primary key, generated by the database.</summary>
    public int Id { get; set; }

    /// <summary>Foreign key to the order. A raw material appears at most once per order.</summary>
    public int OrderNumber { get; set; }

    /// <summary>The order, when loaded.</summary>
    public ProductionOrder Order { get; set; } = null!;

    /// <summary>Position, copied from the recipe line order (design 7.3 lists materials in this order).</summary>
    public int LineNo { get; set; }

    /// <summary>Foreign key to the raw material.</summary>
    public int RawMaterialId { get; set; }

    /// <summary>The raw material, when loaded.</summary>
    public Item RawMaterial { get; set; } = null!;

    // ---- Fixed at creation -------------------------------------------------------------------------------

    /// <summary>AC-08.4: the recipe amount per unit, copied when the order was created (6 decimal places).</summary>
    public decimal AmountPerUnit { get; set; }

    /// <summary>P: round3(<see cref="AmountPerUnit"/> × ordered quantity), fixed at creation.</summary>
    public decimal PlannedAmount { get; set; }

    // ---- Fixed at send -----------------------------------------------------------------------------------

    /// <summary>D-6: L, the free leftover allocated to this order at the moment of sending (D-5).</summary>
    public decimal? LeftoverApplied { get; set; }

    /// <summary>D-7: S, the quantity sent from the Warehouse. May be 0 when leftover covers the need.</summary>
    public decimal? WarehouseSend { get; set; }

    /// <summary>D-8: production storage stock just before the send, minus <see cref="LeftoverApplied"/>.</summary>
    public decimal? CarriedLeftover { get; set; }

    /// <summary>D-3: total sent through complementary orders. Set to 0 at send, then increased by each complementary send.</summary>
    public decimal? ComplementarySends { get; set; }

    // ---- Fixed at completion -----------------------------------------------------------------------------

    /// <summary>PRD section 6 row 1: the physical total of leftover in production storage, entered at completion.</summary>
    public decimal? LeftoverEntered { get; set; }

    /// <summary>D-9: <see cref="LeftoverEntered"/> − <see cref="CarriedLeftover"/>.</summary>
    public decimal? LeftoverRemaining { get; set; }

    /// <summary>D-9: leftover applied + warehouse send + complementary sends − leftover remaining.</summary>
    public decimal? ActualUsage { get; set; }

    /// <summary>D-9: amount per unit × produced quantity.</summary>
    public decimal? RequiredForActualOutput { get; set; }

    /// <summary>D-9: actual usage − required for actual output. Positive means more was used than required.</summary>
    public decimal? UsageVariance { get; set; }

    /// <summary>D-9: usage variance ÷ required × 100, stored rounded to 6 places (architecture 3.1).</summary>
    public decimal? UsageVariancePercent { get; set; }

    /// <summary>AC-20.4: whether |usage variance %| is above the tolerance, decided from the unrounded percentage.</summary>
    public bool? UsageVarianceAboveTolerance { get; set; }
}
